    private static string Canonical(Scene scene,PlayerEntity player,TrooperPirateBlasterRuntime blaster)
    {
        using var bytes=new MemoryStream();using var w=new BinaryWriter(bytes);var marks=new List<(string Name,int End)>();void Mark(string name)=>marks.Add((name,(int)bytes.Position));void V(Vector3 p){w.Write(p.X);w.Write(p.Y);w.Write(p.Z);}void M(Matrix4 m){for(int r=0;r<4;r++)for(int c=0;c<4;c++)w.Write(m[r,c]);}
        void Owner(WeaponOwnerContext o){w.Write(o.IsValid);w.Write(o.MatchId==blaster.Owner.MatchId);w.Write(o.AuthorityEpoch==(ulong)scene.LifetimeGeneration);w.Write(o.Slot);w.Write(o.Generation);w.Write(o.Life);}
        void Beam(BeamProjectileEntity b){w.Write(b.Lifespan);V(b.Position);w.Write(b.Speed);V(b.Direction);w.Write((uint)b.Flags);w.Write(b.Age);w.Write(b.Owner is PlayerEntity p?p.SlotIndex:255);w.Write(b.ModCustomShot!=null);if(b.ModCustomShot is{} s){Owner(s.Owner);w.Write(s.Sequence);w.Write(s.Identity.Weapon.ToString());}}
