        foreach(var p in scene.Players.Items.Where(p=>p.LoadFlags.TestFlag(LoadFlags.Active)))
        {
            w.Write(p.SlotIndex);w.Write(p.IsBot);w.Write(p.Health);V(p.Position);V(p.Speed);V(p.FacingVector);w.Write((uint)p.Flags1);w.Write((uint)p.Flags2);w.Write((uint)p.LoadFlags);w.Write(p.IsAltForm);w.Write(p.IsMorphing);w.Write(p.IsUnmorphing);w.Write((int)p.CurrentWeapon);w.Write((int)p.GunAnimation);w.Write((int)Anim(p,1));w.Write((int)Anim(p,2));w.Write(p.ModPirateUa);w.Write(p.EquipInfo.ChargeLevel);Mark("player"+p.SlotIndex+"/native-scalars");
            foreach(string field in new[]{"_muzzlePos","_aimVec","_gunVec1","_gunVec2","_gunDrawPos"})V((Vector3)typeof(PlayerEntity).GetField(field,Hidden)!.GetValue(p)!);
            foreach(int a in (int[])typeof(PlayerEntity).GetField("_ammo",Hidden)!.GetValue(p)!)w.Write(a);foreach(var model in p.GetModels()){w.Write(model.Model.Name);foreach(int f in model.AnimInfo.Frame)w.Write(f);}foreach(var b in p.EquipInfo.Beams)Beam(b);Mark("player"+p.SlotIndex+"/aim-models-beams");
            if(p.IsBot)foreach(var field in p.AiData.GetType().GetFields(Hidden|BindingFlags.Public).Where(f=>f.FieldType.IsPrimitive||f.FieldType.IsEnum||f.FieldType==typeof(Vector3)).OrderBy(f=>f.Name,StringComparer.Ordinal)){w.Write(field.Name);w.Write(Convert.ToString(field.GetValue(p.AiData),System.Globalization.CultureInfo.InvariantCulture)??"");}
        }
        Mark("players/ai");Owner(blaster.Owner);w.Write(blaster.Available(player));w.Write(blaster.Selected(player));w.Write(blaster.Snapshot.ToString());w.Write(((PirateBurstTimeline)typeof(TrooperPirateBlasterRuntime).GetField("_timeline",Hidden)!.GetValue(blaster)!).Snapshot.ToString());foreach(var beam in blaster.Beams.ToArray())Beam(beam);Mark("private-weapon-owner-timeline-beams");
        foreach(var p in scene.Players.Items)w.Write(blaster.IsMarked(player,p));if(blaster.LastImpact is{} impact){w.Write(true);w.Write(impact.Weapon.ToString());Owner(impact.Source.Owner);w.Write(impact.Source.Sequence);w.Write(impact.VictimSlot);w.Write(impact.Tick);w.Write(impact.Damage);w.Write(impact.TurretDamage);w.Write(impact.HitTurret);w.Write(impact.Headshot);w.Write(impact.Lethal);V(impact.Point);}else w.Write(false);
        Mark("marks/impact");foreach(var value in scene.GameState.Kills.Concat(scene.GameState.Deaths).Concat(scene.GameState.Points).Concat(scene.GameState.ShotsFired).Concat(scene.GameState.ShotsHit).Concat(scene.GameState.MatchDamageDealt).Concat(scene.GameState.MatchDamageTaken))w.Write(value);
        Mark("game-totals");foreach(string name in new[]{"_chargeEffect","_muzzleEffect"})
        {
            var effect=typeof(PlayerEntity).GetField(name,Hidden)!.GetValue(player) as EffectEntry;w.Write(effect!=null);if(effect==null)continue;w.Write(effect.EffectId);w.Write(effect.Elements.Count);foreach(var element in effect.Elements){M(element.OwnTransform);M(element.Transform);w.Write(element.Expired);w.Write(element.Particles.Count);foreach(var p in element.Particles){w.Write(p.CreationTime);w.Write(p.ExpirationTime);w.Write(p.Lifespan);w.Write(p.ParticleId);V(p.Position);V(p.Speed);w.Write(p.Red);w.Write(p.Green);w.Write(p.Blue);w.Write(p.Alpha);w.Write(p.Scale);w.Write(p.Rotation);}}}
        Mark("native-effects");if(player.ModGetFirstPersonGunTransform(out var gun)){w.Write(true);M(gun);}else w.Write(false);if(player.ModGetFirstPersonEffectTransform(out var effectMatrix)){w.Write(true);M(effectMatrix);}else w.Write(false);
        Mark("prepared-native-transforms");var encoded=bytes.ToArray();CanonicalDiagnostics.Add((encoded,marks.ToArray()));return Convert.ToHexStringLower(SHA256.HashData(encoded));
    }
