    {var text=new StringBuilder();text.Append(scene.FrameCount).Append('|').Append(player.Health).Append('|').Append(player.Position).Append('|').Append(player.Speed).Append('|').Append(player.ModAmmo).Append('|').Append(player.CurrentWeapon).Append('|').Append(blaster.Owner).Append('|').Append(blaster.Snapshot).Append('|').Append(blaster.LastImpact).Append('|').Append(scene.Random.Rng1).Append('|').Append(scene.Random.Rng2).Append('|').Append(Rng.Rng1).Append('|').Append(Rng.Rng2);foreach(string name in new[]{"_muzzlePos","_aimVec","_gunVec1"})text.Append('|').Append(typeof(PlayerEntity).GetField(name,Hidden)!.GetValue(player));foreach(var beam in blaster.Beams.ToArray())text.Append('|').Append(beam.Lifespan).Append(',').Append(beam.Position).Append(',').Append(beam.Direction).Append(',').Append(beam.Flags).Append(',').Append(beam.ModCustomShot);return text.ToString();}
    private static string Hash(string path){using var f=File.OpenRead(path);return Convert.ToHexStringLower(SHA256.HashData(f));}
    private static string Inventory(string root){using var hash=IncrementalHash.CreateHash(HashAlgorithmName.SHA256);var pending=new Stack<string>();pending.Push(root);int files=0;long bytes=0;while(pending.Count>0){string directory=pending.Pop();if((File.GetAttributes(directory)&FileAttributes.ReparsePoint)!=0)throw new InvalidDataException("Native inventory alias");foreach(string child in Directory.GetDirectories(directory).Order(StringComparer.Ordinal).Reverse())pending.Push(child);foreach(string file in Directory.GetFiles(directory).Order(StringComparer.Ordinal)){if(++files>65536||(bytes+=new FileInfo(file).Length)>1024L*1024*1024||(File.GetAttributes(file)&FileAttributes.ReparsePoint)!=0)throw new InvalidDataException("Native inventory bound");hash.AppendData(Encoding.UTF8.GetBytes(Path.GetRelativePath(root,file)));hash.AppendData(new byte[]{0});hash.AppendData(Convert.FromHexString(Hash(file)));}}return Convert.ToHexStringLower(hash.GetHashAndReset());}
